custom-token-exchange:
// Code Action sandbox API. Calls are recorded and applied after the handler completes; methods return no result.

interface ActionExchangeUserAttributes {
    /** The user's id within the named connection, not a full AuthHero user_id. */
    user_id: string;
    email?: string;
    email_verified?: boolean;
    phone_number?: string;
    phone_verified?: boolean;
    username?: string;
    name?: string;
    given_name?: string;
    family_name?: string;
    nickname?: string;
    picture?: string;
}

interface ActionExchangeUserOptions {
    /** Defaults to create_if_not_exists. */
    creationBehavior?: "create_if_not_exists" | "none";
    /** Defaults to none. */
    updateBehavior?: "replace" | "none";
}

type ActionAPI = {
    /** Validate the subject token, then call exactly one user selector or reject it. */
    authentication: {
        /** Select an existing full AuthHero user_id. */
        setUserById(userId: string): void;
        /** Select a user by connection name and validated user attributes. */
        setUserByConnection(connection: string, attributes: ActionExchangeUserAttributes, options?: ActionExchangeUserOptions): void;
    };
    access: {
        deny(code: string, reason?: string): void;
        rejectInvalidSubjectToken(reason?: string): void;
    };
};
